    boolean existsByItemName(String itemName);
}

public interface ItemJpaRepository extends JpaRepository<Item, Long> {

    @Query("select i from Item i " +
           "where i.itemName like :itemName and i.price <= :price")
    List<Item> search(@Param("itemName") String itemName,
                      @Param("price") Integer price);

    @Query("select new hello.dto.ItemDto(i.id, i.itemName) from Item i")
    List<ItemDto> findAllDto();

    @Query(value = "select * from item where item_name = ?1",
           nativeQuery = true)
    List<Item> findNative(String itemName);

    @Modifying(clearAutomatically = true)
    @Query("update Item i set i.price = i.price * 1.1 where i.price < :price")
    int raisePrice(@Param("price") Integer price);
}

